export function criarCadastro() {
  return { usuarios: [], proximoId: 1 };
}

export function cadastrarUsuario(cadastro, usuario, hashSenha) {
  if (!cadastro || !Array.isArray(cadastro.usuarios)) {
    throw new Error('cadastro inválido');
  }
  if (!usuario || typeof usuario.nome !== 'string' || usuario.nome.trim() === '') {
    throw new Error('nome precisa ser texto não vazio');
  }
  if (typeof usuario.email !== 'string' || !usuario.email.includes('@')) {
    throw new Error('email precisa conter @');
  }
  if (typeof usuario.senha !== 'string' || usuario.senha === '') {
    throw new Error('senha não pode ser vazia');
  }
  const novo = {
    id: cadastro.proximoId,
    nome: usuario.nome,
    email: usuario.email,
    senhaHash: hashSenha(usuario.senha),
  };
  cadastro.usuarios.push(novo);
  cadastro.proximoId += 1;
  return novo;
}

export function buscarPorEmail(cadastro, email) {
  if (!cadastro || !Array.isArray(cadastro.usuarios)) {
    throw new Error('cadastro inválido');
  }
  return cadastro.usuarios.find((usuario) => usuario.email === email);
}

