import { buscarPorEmail } from './usuarios.mjs';

export function criarSistema() {
  return { sessoes: {} };
}

export function abrirSessao(sistema, usuario, token) {
  if (!sistema || typeof sistema.sessoes !== 'object' || sistema.sessoes === null) {
    throw new Error('sistema inválido');
  }
  if (typeof token !== 'string' || token.trim() === '') {
    throw new Error('token precisa ser texto não vazio');
  }
  if (!usuario || typeof usuario.email !== 'string') {
    throw new Error('usuário inválido');
  }
  sistema.sessoes[token] = usuario.email;
  return token;
}

export function usuarioDaSessao(sistema, token, cadastro) {
  if (!sistema || typeof sistema.sessoes !== 'object' || sistema.sessoes === null) {
    throw new Error('sistema inválido');
  }
  const email = sistema.sessoes[token];
  if (email === undefined) return undefined;
  return buscarPorEmail(cadastro, email);
}

export function encerrarSessao(sistema, token) {
  if (!sistema || typeof sistema.sessoes !== 'object' || sistema.sessoes === null) {
    throw new Error('sistema inválido');
  }
  if (sistema.sessoes[token] === undefined) return false;
  sistema.sessoes[token] = undefined;
  return true;
}

