import { buscarPorEmail } from './usuarios.mjs';
import { abrirSessao } from './sessoes.mjs';

export function fazerLogin(cadastro, email, senha, hashSenha) {
  const usuario = buscarPorEmail(cadastro, email);
  if (!usuario) return null;
  if (hashSenha(senha) !== usuario.senhaHash) return null;
  return usuario;
}

export function loginComToken(sistema, cadastro, email, senha, hashSenha, gerarToken) {
  const usuario = fazerLogin(cadastro, email, senha, hashSenha);
  if (!usuario) return null;
  const token = gerarToken();
  abrirSessao(sistema, usuario, token);
  return token;
}

export function sanitizarBusca(termo) {
  if (typeof termo !== 'string') {
    throw new Error('termo precisa ser texto');
  }
  return termo.replace(/'/g, "''").replace(/%/g, '\\%').replace(/_/g, '\\_');
}

// Busca com "contém" tratando tudo como TEXTO LITERAL: o termo e o texto
// procurado passam pela MESMA sanitização — ' vira '', % vira \% etc.
// Assim o que o usuário digitou nunca vira coringa (nem SQL) na busca.
export function buscarUsuariosPorTermo(cadastro, termo) {
  if (!cadastro || !Array.isArray(cadastro.usuarios)) {
    throw new Error('cadastro inválido');
  }
  const termoLimpo = sanitizarBusca(termo);
  return cadastro.usuarios.filter((usuario) => {
    const nomeLimpo = sanitizarBusca(usuario.nome);
    const emailLimpo = sanitizarBusca(usuario.email);
    return nomeLimpo.includes(termoLimpo) || emailLimpo.includes(termoLimpo);
  });
}

