import { test } from 'node:test';
import assert from 'node:assert/strict';
import { criarCadastro, cadastrarUsuario, buscarPorEmail } from './lib/usuarios.mjs';
import { criarSistema, abrirSessao, usuarioDaSessao, encerrarSessao } from './lib/sessoes.mjs';
import { fazerLogin, loginComToken, sanitizarBusca, buscarUsuariosPorTermo } from './lib/autenticacao.mjs';

// hash SIMULADO e determinístico — o teste não usa criptografia de verdade
const hashSenha = (senha) => 'sim-' + senha;

test('cadastrarUsuario valida e guarda SÓ o hash da senha, nunca o texto puro', () => {
  const cadastro = criarCadastro();
  const ana = cadastrarUsuario(cadastro, { nome: 'Ana', email: 'ana@clinica.com', senha: '123456' }, hashSenha);
  assert.equal(ana.id, 1);
  assert.equal(ana.senhaHash, 'sim-123456');
  assert.ok(!('senha' in ana), 'a senha em texto puro não pode ser guardada');
  assert.equal(cadastro.usuarios.length, 1);
  assert.equal(buscarPorEmail(cadastro, 'ana@clinica.com').nome, 'Ana');
  assert.throws(() => cadastrarUsuario(cadastro, { nome: '', email: 'bia@clinica.com', senha: '123' }, hashSenha));
  assert.throws(() => cadastrarUsuario(cadastro, { nome: 'Bia', email: 'sem-arroba', senha: '123' }, hashSenha));
  assert.throws(() => cadastrarUsuario(cadastro, { nome: 'Bia', email: 'bia@clinica.com', senha: '' }, hashSenha));
});

test('fazerLogin acerta com a senha certa e devolve null com senha errada ou email inexistente', () => {
  const cadastro = criarCadastro();
  cadastrarUsuario(cadastro, { nome: 'Ana', email: 'ana@clinica.com', senha: '123456' }, hashSenha);
  assert.equal(fazerLogin(cadastro, 'ana@clinica.com', '123456', hashSenha).email, 'ana@clinica.com');
  assert.equal(fazerLogin(cadastro, 'ana@clinica.com', 'senha-errada', hashSenha), null);
  assert.equal(fazerLogin(cadastro, 'ninguem@clinica.com', '123456', hashSenha), null);
});

test('loginComToken devolve um token e usuarioDaSessao reconhece (usa os três arquivos)', () => {
  const cadastro = criarCadastro();
  cadastrarUsuario(cadastro, { nome: 'Ana', email: 'ana@clinica.com', senha: '123456' }, hashSenha);
  const sistema = criarSistema();
  const token = loginComToken(sistema, cadastro, 'ana@clinica.com', '123456', hashSenha, () => 'tok-1');
  assert.equal(token, 'tok-1');
  assert.equal(usuarioDaSessao(sistema, 'tok-1', cadastro).nome, 'Ana');
  assert.equal(usuarioDaSessao(sistema, 'tok-inexistente', cadastro), undefined);
  assert.equal(loginComToken(sistema, cadastro, 'ana@clinica.com', 'errada', hashSenha, () => 'tok-2'), null);
  assert.equal(usuarioDaSessao(sistema, 'tok-2', cadastro), undefined);
});

test('abrirSessao valida o token e encerrarSessao derruba a sessão', () => {
  const sistema = criarSistema();
  const cadastro = criarCadastro();
  assert.throws(() => abrirSessao(sistema, { email: 'ana@clinica.com' }, ''));
  assert.equal(encerrarSessao(sistema, 'tok-x'), false);
  abrirSessao(sistema, { email: 'ana@clinica.com' }, 'tok-1');
  assert.equal(encerrarSessao(sistema, 'tok-1'), true);
  assert.equal(encerrarSessao(sistema, 'tok-1'), false);
  assert.equal(usuarioDaSessao(sistema, 'tok-1', cadastro), undefined);
});

test('sanitizarBusca escapa aspas e coringas e recusa termo que não é texto', () => {
  assert.equal(sanitizarBusca("O'Neil"), "O''Neil");
  assert.equal(sanitizarBusca('100%'), '100\\%');
  assert.equal(sanitizarBusca('_'), '\\_');
  assert.equal(sanitizarBusca('ana'), 'ana');
  assert.throws(() => sanitizarBusca(42));
});

test('buscarUsuariosPorTermo trata o termo como TEXTO LITERAL — injeção não pesca ninguém', () => {
  const cadastro = criarCadastro();
  cadastrarUsuario(cadastro, { nome: 'Ana', email: 'ana@clinica.com', senha: '123' }, hashSenha);
  cadastrarUsuario(cadastro, { nome: "Bia O'Neil", email: 'bia@clinica.com', senha: '123' }, hashSenha);
  cadastrarUsuario(cadastro, { nome: 'Carla 100%', email: 'carla@clinica.com', senha: '123' }, hashSenha);
  assert.deepEqual(buscarUsuariosPorTermo(cadastro, "O'Neil").map((u) => u.nome), ["Bia O'Neil"]);
  assert.deepEqual(buscarUsuariosPorTermo(cadastro, '100%').map((u) => u.nome), ['Carla 100%']);
  assert.deepEqual(buscarUsuariosPorTermo(cadastro, "' OR '1'='1"), []);
  assert.deepEqual(buscarUsuariosPorTermo(cadastro, 'Ana').map((u) => u.nome), ['Ana']);
  assert.equal(buscarUsuariosPorTermo(cadastro, '').length, 3);
});
